"use client";

import { useEffect, useState } from "react";
import Link from "next/link";
import { motion } from "framer-motion";
import { services } from "@/data/services";
import { Globe, Cuboid, Palette, Share2, Video, ArrowRight, ArrowLeft } from "lucide-react";
import { LiquidButton } from "@/components/ui/liquid-glass-button";

const iconMap: Record<string, React.ElementType> = {
  "Globe": Globe,
  "Cuboid": Cuboid,
  "Palette": Palette,
  "Share2": Share2,
  "Video": Video,
};

export default function Services() {
  const [lang, setLang] = useState<"ar" | "en">("ar");

  useEffect(() => {
    const checkLang = () => {
      setLang(document.documentElement.lang === "en" ? "en" : "ar");
    };
    checkLang();
    const observer = new MutationObserver(checkLang);
    observer.observe(document.documentElement, { attributes: true, attributeFilter: ["lang"] });
    return () => observer.disconnect();
  }, []);

  const featuredServices = services.filter(service => service.featured);
  const isRtl = lang === "ar";

  return (
    <section className="relative w-full py-20 lg:py-32 overflow-hidden border-t border-white/5">
      <div className="container mx-auto px-4 relative z-10">
        
        {/* Header Area */}
        <div className="flex flex-col md:flex-row items-center justify-between gap-8 mb-16">
          <div className="max-w-2xl">
            <span className="inline-flex items-center rounded-full px-3 py-1 text-sm font-medium bg-brand-primary/10 text-brand-primary mb-4 border border-brand-primary/20">
              {isRtl ? "خدماتنا" : "Our Services"}
            </span>
            <h2 className="text-3xl md:text-5xl font-bold tracking-tight text-white mb-4">
              {isRtl 
                ? "حلول رقمية متكاملة لنمو أعمالك" 
                : "End-to-End Digital Solutions for Growth"}
            </h2>
            <p className="text-lg text-muted-foreground">
              {isRtl 
                ? "نقدم مجموعة شاملة من الخدمات الرقمية والإبداعية المصممة خصيصاً لتلبية احتياجاتك وتحقيق أهدافك بفعالية واحترافية عالية." 
                : "We offer a comprehensive suite of digital and creative services tailored to meet your needs and achieve your goals with high efficiency and professionalism."}
            </p>
          </div>
          
          <Link href="/services" className="shrink-0 hidden md:block">
            <LiquidButton className="px-6 h-12 rounded-full text-white">
              {isRtl ? "عرض جميع الخدمات" : "View All Services"}
            </LiquidButton>
          </Link>
        </div>

        {/* Cards Grid */}
        <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
          {featuredServices.map((service, index) => {
            const Icon = iconMap[service.icon];
            return (
              <motion.div
                key={service.id}
                initial={{ opacity: 0, y: 20 }}
                whileInView={{ opacity: 1, y: 0 }}
                viewport={{ once: true }}
                transition={{ duration: 0.5, delay: index * 0.1 }}
                className="group relative flex flex-col justify-between h-full rounded-2xl bg-black/60 backdrop-blur-md border border-white/10 p-8 transition-all duration-300 hover:border-[#7BC1FF]/50 hover:shadow-[0_0_30px_rgba(123,193,255,0.15)] overflow-hidden"
              >
                {/* Background Glow Effect */}
                <div className="absolute top-0 right-0 -mr-16 -mt-16 w-32 h-32 rounded-full bg-brand-primary/10 blur-[50px] transition-all duration-500 group-hover:bg-brand-primary/20 group-hover:scale-150" />

                <div>
                  <div className="mb-6 inline-flex items-center justify-center w-14 h-14 rounded-full bg-white/5 border border-white/10 text-[#7BC1FF] transition-transform duration-300 group-hover:scale-110">
                    {Icon && <Icon className="w-6 h-6" />}
                  </div>
                  <h3 className="text-2xl font-semibold text-white mb-4">
                    {service.title[lang]}
                  </h3>
                  <p className="text-muted-foreground leading-relaxed">
                    {service.description[lang]}
                  </p>
                </div>

                <div className="mt-8 pt-8 border-t border-white/5">
                  <Link 
                    href={service.href}
                    className="inline-flex items-center gap-2 text-sm font-medium text-white transition-colors duration-200 hover:text-[#7BC1FF]"
                  >
                    {isRtl ? "اعرف المزيد" : "Learn More"}
                    {isRtl ? (
                      <ArrowLeft className="w-4 h-4 transition-transform duration-300 group-hover:-translate-x-1" />
                    ) : (
                      <ArrowRight className="w-4 h-4 transition-transform duration-300 group-hover:translate-x-1" />
                    )}
                  </Link>
                </div>
              </motion.div>
            );
          })}
        </div>

        {/* Mobile View All Button */}
        <div className="mt-10 flex justify-center md:hidden">
          <Link href="/services" className="w-full">
            <LiquidButton className="w-full px-6 h-12 rounded-full text-white">
              {isRtl ? "عرض جميع الخدمات" : "View All Services"}
            </LiquidButton>
          </Link>
        </div>

      </div>
    </section>
  );
}
